/**
 * 跨半边契约（D31）：`/auth/*` 路由路径、登录页查询键与端点载荷形状，host 与 client 两个半边的
 * 唯一来源。载荷类型在同目录的 `payloads.ts`，经本文件再导出（两个桥只认本文件）。
 *
 * 这里只放纯常量、纯函数与纯类型，不 import 自身以外的任何东西（`slice:check` 强制），所以它能
 * 同时进 Node 的 host 构建与浏览器的 client bundle，而不会把任何一侧的依赖带给另一侧。两个半边
 * 各经一个桥进来：
 * host 走 `src/host/shared/protocol/index.ts`，client 走 `src/client/shared/api/protocol.ts`。
 *
 * 改这里的值就是改对外契约（书签、反代规则、dsh 前端的跳转都认这些路径）：先改
 * `index.test.ts` 里钉住的值，再改这里。
 */

export type {
  AdminResetErrorBody,
  AdminResetRequest,
  AdminResetResponse,
  AdminUserRow,
  LockedErrorBody,
  PasswordChangeErrorBody,
  PasswordChangeRequest,
  PasswordChangeResponse,
  PasskeyAdminErrorBody,
  PasskeyAssertionRequest,
  PasskeyListResponse,
  PasskeyLoginErrorBody,
  PasskeyLoginOptionsResponse,
  PasskeyRegistrationOptionsResponse,
  PasskeyRegistrationRequest,
  PasskeyRemoveRequest,
  PasskeySettingsRequest,
  PasskeySettingsResponse,
  PasskeySummary,
  PasswordRule,
  PolicyErrorBody,
  SessionKind,
  StatusResponse,
  Unchecked,
  UserRole,
  UsersErrorBody,
  UsersResponse,
} from "./payloads.js";

/** 本插件全部端点的前缀；`prefix` 兜底路由挂在这里，gate 白名单也按它放行。 */
export const AUTH_PATH_PREFIX = "/auth";

/** 登录页（GET 渲染、POST 提交）。 */
export const LOGIN_PATH = "/auth/login";

/** 登出（POST-only，`next` 只从 query 取）。 */
export const LOGOUT_PATH = "/auth/logout";

/** 会话探针（只认 cookie）。 */
export const STATUS_PATH = "/auth/status";

/** passkey 登录 begin（匿名 POST，返回 options + 下发 ceremony cookie）。 */
export const PASSKEY_OPTIONS_PATH = "/auth/passkey/options";

/** passkey 登录 finish（匿名表单 POST，断言 → 发会话）。 */
export const PASSKEY_LOGIN_PATH = "/auth/passkey/login";

/** 已登录用户自己的凭据列表（GET JSON）。 */
export const PASSKEY_PATH = "/auth/passkey";

/** 注册 begin（已登录 + 再认证的表单 POST，返回 options + 下发 ceremony cookie）。 */
export const PASSKEY_REGISTER_OPTIONS_PATH = "/auth/passkey/register/options";

/** 注册 finish（已登录表单 POST，attestation → 写 users.yaml）。 */
export const PASSKEY_REGISTER_PATH = "/auth/passkey/register";

/** 删除自己的凭据（已登录表单 POST；删最后一把或 `--all` 需再认证）。 */
export const PASSKEY_REMOVE_PATH = "/auth/passkey/remove";

/** 条件 UI（登录页 passkey 自动填充）开关（admin GET/POST）。 */
export const PASSKEY_SETTINGS_PATH = "/auth/passkey/settings";

/** 自助改密（GET SSR 页，POST 提交）；也是受限会话被拒时的导航目标。 */
export const PASSWORD_PATH = "/auth/password";

/** 管理面：用户列表。 */
export const USERS_PATH = "/auth/users";

/** 管理面：管理员重置他人口令。 */
export const USERS_PASSWORD_PATH = "/auth/users/password";

/** 首次引导：校验 dsh launch token 并签发一次性的 bootstrap 会话（GET）。 */
export const BOOTSTRAP_PATH = "/auth/bootstrap";

/** 首次配置向导页（GET 渲染、POST 提交）；也是 bootstrap 会话被拒时的导航目标。 */
export const SETUP_PATH = "/auth/setup";

/** 向导完成后回首页：只认会话 cookie，302 到 dsh 的 `/?token=`。 */
export const CONTINUE_PATH = "/auth/continue";

/**
 * bootstrap 会话的 `kind` 值：只在首次引导通道签发，TTL 有上限，只能访问本插件的
 * `/auth/*`。向导完成后被整体吊销，不是第二种长期登录方式。
 */
export const BOOTSTRAP_SESSION_KIND = "bootstrap";

/** 登录页 `notice` 白名单键：改密成功后被登出。 */
export const PASSWORD_CHANGED_NOTICE = "password-changed";

/** 改密成功后 client 把当前设备送去的登录页（回首页，并带上被登出的原因键）。 */
export const PASSWORD_CHANGED_LOGIN_URL = `${LOGIN_PATH}?next=%2F&notice=${PASSWORD_CHANGED_NOTICE}`;

/** 设置页「退出登录」按钮的提交目标（登出后回首页）。 */
export const LOGOUT_URL = `${LOGOUT_PATH}?next=/`;

/** `pathname` 是否落在本插件的 `/auth` 命名空间里（恰好是前缀本身，或在它下面）。 */
export function isAuthPath(pathname: string): boolean {
  return pathname === AUTH_PATH_PREFIX || pathname.startsWith(`${AUTH_PATH_PREFIX}/`);
}

/** 带 `next`（与可选 `stage`）的登录页 URL。 */
export function loginPath(next: string, stage?: "password"): string {
  const base = `${LOGIN_PATH}?next=${encodeURIComponent(next)}`;
  return stage === undefined ? base : `${base}&stage=${stage}`;
}
